        realizes bsegs (mkCfg msF' mo') K) ->
    as_VIS H s msF = mkst regs (Z_to_bv 64 0xa4068) mem rom -> as_AKREL H s (mkCfg msF mo) ->
    realizes bsegs (mkCfg msF mo) K.
