        frame_mod mem mem' (regL_w sp0) -> stk_ok RSEGS mem' (Z_to_bv 64 (bv_unsigned sp0 - 128)) MSTK ->
        realizes bsegs (mkCfg msF' mo') K) ->
    as_VIS H s msF = mkst regs (Z_to_bv 64 0xa4084) mem rom -> as_AKREL H s (mkCfg msF mo) ->
    realizes bsegs (mkCfg msF mo) K.
