  Definition am_regs (regs : bvmap 5 word) (pp : word) (A len cap n : Z) : Prop :=
    albase_regs regs pp /\ getr regs 9 = Z_to_bv 64 A /\ getr regs 19 = Z_to_bv 64 len /\ getr regs 21 = Z_to_bv 64 cap
