  Definition abuf_bytes (mem : word -> option byte) (A : Z) (data : list byte) : Prop :=
    forall i, (i < length data)%nat -> rdn RSEGS mem (Z_to_bv 64 (A + Z.of_nat i)) 1 = Some [nth i data (Z_to_bv 8 0)].

